import sys, os, gzip, json, glob, re
root=sys.argv[1]
WS=re.compile(r'<workspace>.*?</workspace>', re.S)
KW=re.compile(r'(portugu|idioma|lingua|língua|language|langue|français|francais|español|espanol|spanish|french|english|ingl[eé]s|deutsch|german|pt-?br|traduz|translate|tradu)', re.I)
def txt(c):
    if isinstance(c,str): return c
    out=[]
    for b in c:
        if isinstance(b,dict):
            if b.get('type') in ('text','input_text','output_text'): out.append(b.get('text',''))
    return ' '.join(out)
for f in sorted(glob.glob(os.path.join(root,'*','*.json.gz'))):
    rec=json.loads(gzip.open(f).read()); req=json.loads(rec['request'])
    turns=[]
    if rec['format']=='anthropic':
        sysp=req.get('system')
        for m in req['messages']:
            c=m['content']
            if isinstance(c,str): c=[{'type':'text','text':c}]
            t=WS.sub('',txt(c)).strip()
            tools=[b['name']+':'+json.dumps(b.get('input'))[:200] for b in c if isinstance(b,dict) and b.get('type')=='tool_use']
            if t or tools: turns.append((m['role'],t,tools))
    else:
        for it in req.get('input',[]):
            if it.get('type')=='function_call': turns.append(('assistant','',[it['name']+':'+it.get('arguments','')[:200]]))
            elif it.get('role') in ('user','assistant'):
                t=WS.sub('',txt(it.get('content'))).strip()
                if t: turns.append((it['role'],t,[]))
    reply=''
    for e in rec['events']:
        try: ev=json.loads(e[5:] if e.startswith('data:') else e)
        except Exception: continue
        if ev.get('type')=='content_block_delta' and ev['delta'].get('type')=='text_delta': reply+=ev['delta']['text']
        if ev.get('type')=='response.completed':
            for o in ev.get('response',{}).get('output',[]):
                if o.get('type')=='message': reply+=' '.join(x.get('text','') for x in o.get('content',[]))
    if reply.strip(): turns.append(('assistant(final)',reply.strip(),[]))
    hits=[i for i,(r,t,_) in enumerate(turns) if r=='user' and KW.search(t) and not t.startswith('JusPrin file-load report') and len(t)<600]
    if not hits: continue
    print('='*100); print('USER',rec['user_id'],'CHAT',rec['chat_id'][:8],'alias',rec['alias'],'fmt',rec['format'])
    for i in hits:
        for r,t,tools in turns[i:i+4]:
            print(f'--- {r}: {t[:900]}'); 
            for x in tools: print('    TOOL',x)
        print('  ...')

