            return std::exchange(unanswered, false) && facts.yes ? std::optional<int>(wxID_YES) : std::nullopt;
        });
        tab->save_preset(*patch.persist_as);
        if (collection.get_selected_preset_name() != *patch.persist_as || collection.current_is_dirty())
